// Project screenshots and videos, shared by the homepage gallery
// (projects.ts) and the project pages (project-page.ts), so both use the same
// resized files and a visitor moving between them downloads each one once.
import { required } from "./dom.ts";

export type View = "desktop" | "mobile";

// Generated by `npm run screenshots`; Vite bundles only the files that exist.
// vite-imagetools resizes each one into a srcset at build time, so phones
// download a smaller copy than the full-size capture. The widths cover the
// sizes each page draws them at, at 1x to 3x pixel density. Sites with a dark
// mode also have a -dark capture, shown while this site is in dark mode.
// (import.meta.glob only takes literal arguments, hence the repetition.)
const SRCSETS = {
  light: {
    desktop: import.meta.glob<string>("../assets/screenshots/*-desktop.webp", {
      eager: true,
      query: { w: "480;720;1080;1440", format: "webp", as: "srcset" },
      import: "default",
    }),
    mobile: import.meta.glob<string>("../assets/screenshots/*-mobile.webp", {
      eager: true,
      query: { w: "200;300;390", format: "webp", as: "srcset" },
      import: "default",
    }),
  },
  dark: {
    desktop: import.meta.glob<string>("../assets/screenshots/*-desktop-dark.webp", {
      eager: true,
      query: { w: "480;720;1080;1440", format: "webp", as: "srcset" },
      import: "default",
    }),
    mobile: import.meta.glob<string>("../assets/screenshots/*-mobile-dark.webp", {
      eager: true,
      query: { w: "200;300;390", format: "webp", as: "srcset" },
      import: "default",
    }),
  },
};

// Generated by `npm run videos` for projects whose hero animates on page load:
// the first few seconds of the page loading, as an H.264 MP4.
const VIDEOS = import.meta.glob<string>("../assets/videos/*.mp4", { eager: true, query: "?url", import: "default" });

const darkTheme = () => document.documentElement.dataset.theme === "dark";

/** The screenshot in this site's current theme, or the light one if the project has no dark capture. */
export const screenshotSrcset = (id: string, view: View): string | undefined =>
  (darkTheme() ? SRCSETS.dark[view][`../assets/screenshots/${id}-${view}-dark.webp`] : undefined) ??
  SRCSETS.light[view][`../assets/screenshots/${id}-${view}.webp`];

/**
 * Show the project's screenshot (in the current theme) in the img, with the
 * frame's skeleton until a new image arrives rather than the previous one.
 * Returns whether the project has this screenshot.
 */
export function showScreenshot(img: HTMLImageElement, id: string, view: View): boolean {
  const srcset = screenshotSrcset(id, view);
  if (!srcset) {
    img.removeAttribute("srcset");
    return false;
  }
  if (img.getAttribute("srcset") !== srcset) {
    img.srcset = srcset;
    img.parentElement?.toggleAttribute("data-loading", !img.complete);
  }
  return true;
}

const reducedMotion = matchMedia("(prefers-reduced-motion: reduce)");

type Connection = { saveData?: boolean; effectiveType?: string };

/** Whether to play videos at all: not for visitors who prefer reduced motion, are saving data or are on a slow connection. */
function videosWanted(): boolean {
  if (reducedMotion.matches) return false;
  const connection = (navigator as Navigator & { connection?: Connection }).connection;
  return !connection?.saveData && !/2g|3g/.test(connection?.effectiveType ?? "");
}

/**
 * Play the project's video, if it has one, over the top of the screenshot in
 * the frame (a .shot), once the frame is on screen. It plays once and holds
 * its last frame. Videos are recorded in the light theme, so projects with
 * dark screenshots don't play theirs while this site is dark. Calling this
 * again for the same video leaves it be, rather than playing it again.
 */
export function showVideo(frame: HTMLElement, id: string, view: View) {
  const name = `${id}-${view}`;
  const current = frame.querySelector<HTMLVideoElement>("video");
  const src = VIDEOS[`../assets/videos/${name}.mp4`];
  const darkShot = Boolean(SRCSETS.dark[view][`../assets/screenshots/${id}-${view}-dark.webp`]);
  const wanted = Boolean(src) && videosWanted() && !(darkTheme() && darkShot);
  if (wanted && current?.dataset.video === name) return;
  current?.remove();
  if (!wanted) return;

  const video = document.createElement("video");
  video.className = "shot-video";
  video.dataset.video = name;
  // Muted and inline, so browsers allow it to play by itself.
  video.muted = video.defaultMuted = true;
  video.playsInline = true;
  video.disablePictureInPicture = true;
  // Nothing downloads until it's on screen.
  video.preload = "none";
  video.setAttribute("aria-hidden", "true");
  video.src = src;
  // Shown once it's playing (faded in by .shot-video): until then, the
  // screenshot underneath stays.
  video.addEventListener("playing", () => video.setAttribute("data-playing", ""), { once: true });
  frame.append(video);

  const observer = new IntersectionObserver(
    ([entry]) => {
      if (!video.isConnected) return observer.disconnect();
      if (!entry.isIntersecting) return;
      observer.disconnect();
      // Refused (iOS Low Power Mode, for one) or unplayable: keep the screenshot.
      video.play().catch(() => video.remove());
    },
    { threshold: 0.5 },
  );
  observer.observe(frame);
}

/** Run the callback whenever this site switches between light and dark (theme.ts sets data-theme). */
export function onThemeChange(callback: () => void) {
  new MutationObserver(callback).observe(document.documentElement, { attributeFilter: ["data-theme"] });
}

/** Clear the frame's skeleton (data-loading on the img's parent) once the image arrives. */
export function showSkeletonWhileLoading(img: HTMLImageElement) {
  const loaded = () => {
    if (img.complete) img.parentElement?.removeAttribute("data-loading");
  };
  img.addEventListener("load", loaded);
  img.addEventListener("error", loaded);
}

// Hover-scroll speed through a screenshot, in rendered pixels per second.
const SCROLL_SPEED = 130;

/**
 * Scroll a frame's screenshot (.browser or .phone, around a .shot) to the
 * bottom while a mouse hovers it, at the same speed however long the page,
 * and back to the top when the mouse leaves or a new screenshot arrives.
 * Touch has no hover to leave, so there a tap scrolls it down and another
 * brings it back up. The .shot is a real scroll container for mice and
 * trackpads (see .shot), so the wheel scrolls it with the browser's own
 * momentum and stops the hover scroll where it's got to. While it's off the
 * top, the frame has data-scrolled (which hides its video).
 */
export function scrollPreview(frame: HTMLElement) {
  const shot = required(frame, ".shot");
  let frameId: number | undefined;
  const stop = () => {
    if (frameId !== undefined) cancelAnimationFrame(frameId);
    frameId = undefined;
  };
  const bottom = () => shot.scrollHeight - shot.clientHeight;

  const scrollDown = () => {
    stop();
    if (reducedMotion.matches) return;
    // Tracked here rather than read back, as browsers may round scrollTop.
    let top = shot.scrollTop;
    let last = performance.now();
    const tick = (now: number) => {
      top = Math.min(top + ((now - last) / 1000) * SCROLL_SPEED, bottom());
      last = now;
      shot.scrollTop = top;
      frameId = top < bottom() ? requestAnimationFrame(tick) : undefined;
    };
    frameId = requestAnimationFrame(tick);
  };
  const scrollUp = () => {
    stop();
    shot.scrollTo({ top: 0, behavior: reducedMotion.matches ? "instant" : "smooth" });
  };

  frame.addEventListener("pointerenter", event => {
    if (event.pointerType !== "touch") scrollDown();
  });
  frame.addEventListener("pointerleave", event => {
    if (event.pointerType !== "touch") scrollUp();
  });
  // A tap (a click straight after a touch) starts or reverses the scroll.
  let touched = false;
  frame.addEventListener("pointerdown", event => (touched = event.pointerType === "touch"));
  frame.addEventListener("click", () => {
    if (!touched) return;
    if (frameId !== undefined || shot.scrollTop > 0) scrollUp();
    else scrollDown();
  });
  frame.addEventListener("wheel", stop, { passive: true });
  shot.addEventListener("scroll", () => frame.toggleAttribute("data-scrolled", shot.scrollTop > 0), {
    passive: true,
  });
  required(frame, ".shot-track").addEventListener("load", () => {
    stop();
    shot.scrollTop = 0;
  });
}
